[{"name": "aplicar_movimiento_stock", "grants": ["postgres=X/postgres", "authenticated=X/postgres", "service_role=X/postgres"], "arguments": "p_id uuid, p_negocio_id uuid, p_sucursal_id uuid, p_producto_id uuid, p_delta numeric, p_tipo text, p_referencia_id uuid, p_fecha_creacion bigint, p_valor_absoluto numeric", "definition": "CREATE OR REPLACE FUNCTION public.aplicar_movimiento_stock(p_id uuid, p_negocio_id uuid, p_sucursal_id uuid, p_producto_id uuid, p_delta numeric, p_tipo text, p_referencia_id uuid, p_fecha_creacion bigint, p_valor_absoluto numeric DEFAULT NULL::numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
            declare
                v_insertadas integer;
                v_ahora bigint := (extract(epoch from now()) * 1000)::bigint;
            begin
                if coalesce(auth.role(), '') <> 'service_role'
                   and not public.es_miembro_del_negocio(p_negocio_id)
                then
                    raise exception 'No autorizado para este negocio';
                end if;

                insert into public.movimientos_stock (
                    id, negocio_id, sucursal_id, producto_id, delta,
                    valor_absoluto, tipo, referencia_id, fecha_creacion
                ) values (
                    p_id, p_negocio_id, p_sucursal_id, p_producto_id, p_delta,
                    p_valor_absoluto, p_tipo, p_referencia_id, p_fecha_creacion
                ) on conflict (id) do nothing;

                get diagnostics v_insertadas = row_count;
                if v_insertadas = 0 then return; end if;

                if p_valor_absoluto is not null then
                    update public.productos
                       set stock_actual = p_valor_absoluto,
                           fecha_actualizacion = v_ahora
                     where id = p_producto_id and negocio_id = p_negocio_id;
                else
                    update public.productos
                       set stock_actual = coalesce(stock_actual, 0) + p_delta,
                           fecha_actualizacion = v_ahora
                    where id = p_producto_id and negocio_id = p_negocio_id;
                end if;

                if p_sucursal_id is not null then
                    insert into public.inventario_sucursales (
                        sucursal_id, producto_id, stock_actual,
                        stock_minimo, fecha_actualizacion
                    ) values (
                        p_sucursal_id, p_producto_id,
                        coalesce(p_valor_absoluto, p_delta), 0, v_ahora
                    )
                    on conflict (sucursal_id, producto_id) do update
                    set stock_actual = case
                        when p_valor_absoluto is not null then p_valor_absoluto
                        else coalesce(inventario_sucursales.stock_actual, 0)
                            + p_delta
                    end,
                    fecha_actualizacion = v_ahora;
                end if;
            end;
            $function$
", "configuration": null, "security_definer": true}, {"name": "aplicar_movimiento_stock_v2", "grants": ["postgres=X/postgres", "authenticated=X/postgres"], "arguments": "p_contract_version integer, p_operation_id uuid, p_negocio_id uuid, p_sucursal_id uuid, p_producto_id uuid, p_effect_kind text, p_effect_value text, p_tipo text, p_referencia_id uuid, p_fecha_origen bigint, p_expected_remote_sequence bigint, p_payload_hash text, p_origin_device_id text", "definition": "CREATE OR REPLACE FUNCTION public.aplicar_movimiento_stock_v2(p_contract_version integer, p_operation_id uuid, p_negocio_id uuid, p_sucursal_id uuid, p_producto_id uuid, p_effect_kind text, p_effect_value text, p_tipo text, p_referencia_id uuid, p_fecha_origen bigint, p_expected_remote_sequence bigint, p_payload_hash text, p_origin_device_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
    v_actor_id uuid;
    v_owner_id uuid;
    v_is_authorized boolean := false;
    v_authority text;
    v_effect_value_bigint bigint;
    v_effect_value_integer integer;
    v_effect_value_canonical text;
    v_canonical_payload text;
    v_computed_hash text;
    v_existing public.inventario_operaciones_v2%rowtype;
    v_global_before integer;
    v_global_after_bigint bigint;
    v_branch_before integer;
    v_branch_after_bigint bigint;
    v_branch_count bigint;
    v_branch_total bigint;
    v_stock_before integer;
    v_stock_after integer;
    v_current_sequence bigint := 0;
    v_next_sequence bigint;
    v_counter_id uuid;
    v_counter_exists boolean := false;
    v_applied_at timestamptz;
    v_warning_codes text[] := array[]::text[];
    v_affected_rows bigint;
begin
    -- Autorizacion explicita. El grant a authenticated no sustituye esta prueba.
    v_actor_id := auth.uid();
    if v_actor_id is null then
        return pg_catalog.jsonb_build_object(
            'contractVersion', '2.0',
            'outcome', 'REJECTED',
            'code', 'AUTH_REQUIRED'
        );
    end if;

    -- Validacion de forma previa a cualquier lock/DML persistente.
    if p_contract_version is distinct from 2
       or p_operation_id is null
       or p_negocio_id is null
       or p_producto_id is null
       or p_fecha_origen is null
       or p_fecha_origen <= 0
       or p_payload_hash is null
       or p_payload_hash !~ '^[0-9a-f]{64}$'
       or p_origin_device_id is null
       or pg_catalog.length(pg_catalog.btrim(p_origin_device_id)) = 0
       or pg_catalog.length(p_origin_device_id) > 128
       or p_effect_kind is null
       or p_effect_kind not in ('DELTA', 'ABSOLUTE')
       or p_tipo is null
       or p_tipo not in (
            'venta', 'devolucion', 'entrada', 'merma', 'conteo',
            'importacion', 'reparacion', 'apartado'
       )
       or (p_effect_kind = 'DELTA' and p_expected_remote_sequence is not null)
       or (p_effect_kind = 'ABSOLUTE' and p_expected_remote_sequence is null)
       or (p_expected_remote_sequence is not null and p_expected_remote_sequence < 0)
    then
        return pg_catalog.jsonb_build_object(
            'contractVersion', '2.0',
            'outcome', 'REJECTED',
            'code', 'INVALID_EFFECT',
            'negocioId', p_negocio_id,
            'operationId', p_operation_id
        );
    end if;

    -- Se acepta sintaxis entera y se normaliza sin redondear: +1/001 -> 1 y -0 -> 0.
    -- Punto, exponente, fraccion y overflow quedan rechazados antes de mutar.
    if p_effect_value is null or p_effect_value !~ '^[+-]?[0-9]+$' then
        return pg_catalog.jsonb_build_object(
            'contractVersion', '2.0',
            'outcome', 'REJECTED',
            'code', 'INVALID_EFFECT',
            'negocioId', p_negocio_id,
            'operationId', p_operation_id
        );
    end if;

    begin
        v_effect_value_bigint := p_effect_value::bigint;
    exception
        when invalid_text_representation or numeric_value_out_of_range then
            return pg_catalog.jsonb_build_object(
                'contractVersion', '2.0',
                'outcome', 'REJECTED',
                'code', 'INVALID_EFFECT',
                'negocioId', p_negocio_id,
                'operationId', p_operation_id
            );
    end;

    if v_effect_value_bigint < -2147483648 or v_effect_value_bigint > 2147483647 then
        return pg_catalog.jsonb_build_object(
            'contractVersion', '2.0',
            'outcome', 'REJECTED',
            'code', 'INVALID_EFFECT',
            'negocioId', p_negocio_id,
            'operationId', p_operation_id
        );
    end if;
    v_effect_value_integer := v_effect_value_bigint::integer;
    v_effect_value_canonical := v_effect_value_integer::text;
    v_authority := case when p_sucursal_id is null then 'GLOBAL' else 'BRANCH' end;

    -- Reproduce exactamente el orden y las representaciones JSON del contrato
    -- canonical-payload.ts. UUID y cantidad llegan normalizados por el cliente v2.
    v_canonical_payload :=
        '{"version":2'
        || ',"operationId":' || pg_catalog.to_json(p_operation_id::text)::text
        || ',"negocioId":' || pg_catalog.to_json(p_negocio_id::text)::text
        || ',"sucursalId":' || case
            when p_sucursal_id is null then 'null'
            else pg_catalog.to_json(p_sucursal_id::text)::text
        end
        || ',"productoId":' || pg_catalog.to_json(p_producto_id::text)::text
        || ',"effect":{"kind":' || pg_catalog.to_json(p_effect_kind)::text
        || ',"value":' || pg_catalog.to_json(v_effect_value_canonical)::text || '}'
        || ',"tipo":' || pg_catalog.to_json(p_tipo)::text
        || ',"referenciaId":' || case
            when p_referencia_id is null then 'null'
            else pg_catalog.to_json(p_referencia_id::text)::text
        end
        || ',"fechaOrigen":' || p_fecha_origen::text
        || ',"expectedRemoteSequence":' || case
            when p_expected_remote_sequence is null then 'null'
            else pg_catalog.to_json(p_expected_remote_sequence::text)::text
        end
        || '}';

    v_computed_hash := pg_catalog.encode(
        pg_catalog.sha256(pg_catalog.convert_to(v_canonical_payload, 'UTF8')),
        'hex'
    );
    if v_computed_hash is distinct from p_payload_hash then
        return pg_catalog.jsonb_build_object(
            'contractVersion', '2.0',
            'outcome', 'CONFLICT',
            'code', 'IDENTITY_PAYLOAD_MISMATCH',
            'negocioId', p_negocio_id,
            'operationId', p_operation_id,
            'payloadHash', p_payload_hash
        );
    end if;

    -- El negocio se bloquea primero para fijar el tenant durante toda la llamada.
    select n."dueño_id"
      into v_owner_id
      from public.negocios as n
     where n.id = p_negocio_id
     for share;
    if not found then
        return pg_catalog.jsonb_build_object(
            'contractVersion', '2.0',
            'outcome', 'REJECTED',
            'code', 'SCOPE_FORBIDDEN',
            'negocioId', p_negocio_id,
            'operationId', p_operation_id
        );
    end if;

    if v_owner_id = v_actor_id then
        v_is_authorized := true;
    else
        perform 1
          from public.usuarios_negocio as un
         where un.negocio_id = p_negocio_id
           and un.user_id = v_actor_id
           and un.activo = true
         for share;
        v_is_authorized := found;
    end if;
    if not v_is_authorized then
        return pg_catalog.jsonb_build_object(
            'contractVersion', '2.0',
            'outcome', 'REJECTED',
            'code', 'SCOPE_FORBIDDEN',
            'negocioId', p_negocio_id,
            'operationId', p_operation_id
        );
    end if;

    -- Serializa la ausencia y presencia de la identidad dentro del tenant. El
    -- prefijo y negocio impiden que la misma UUID de otro tenant comparta la key.
    perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'inventory-v2-operation:' || p_negocio_id::text || ':' || p_operation_id::text,
            0
        )
    );

    select ledger.*
      into v_existing
      from public.inventario_operaciones_v2 as ledger
     where ledger.negocio_id = p_negocio_id
       and ledger.operacion_id = p_operation_id;

    if found then
        if v_existing.payload_version = p_contract_version
           and v_existing.payload_hash = p_payload_hash
           and v_existing.producto_id = p_producto_id
           and v_existing.sucursal_id is not distinct from p_sucursal_id
           and v_existing.authority_kind = v_authority
           and v_existing.effect_kind = p_effect_kind
           and v_existing.effect_value = v_effect_value_integer
           and v_existing.tipo = p_tipo
           and v_existing.referencia_id is not distinct from p_referencia_id
           and v_existing.fecha_origen = p_fecha_origen
           and v_existing.expected_remote_sequence is not distinct from p_expected_remote_sequence
        then
            return pg_catalog.jsonb_build_object(
                'contractVersion', '2.0',
                'outcome', 'ALREADY_APPLIED',
                'code', 'ALREADY_APPLIED',
                'negocioId', v_existing.negocio_id,
                'operationId', v_existing.operacion_id,
                'payloadHash', v_existing.payload_hash,
                'authority', v_existing.authority_kind,
                'productoId', v_existing.producto_id,
                'sucursalId', v_existing.sucursal_id,
                'remoteSequence', v_existing.remote_sequence::text,
                'stockBefore', v_existing.stock_before::text,
                'stockAfter', v_existing.stock_after::text,
                'appliedAt', v_existing.applied_at,
                'warningCodes', pg_catalog.to_jsonb(v_existing.warning_codes)
            );
        end if;

        return pg_catalog.jsonb_build_object(
            'contractVersion', '2.0',
            'outcome', 'CONFLICT',
            'code', 'IDENTITY_PAYLOAD_MISMATCH',
            'negocioId', p_negocio_id,
            'operationId', p_operation_id,
            'payloadHash', p_payload_hash,
            'remotePayloadHash', v_existing.payload_hash,
            'authority', v_existing.authority_kind,
            'productoId', v_existing.producto_id,
            'sucursalId', v_existing.sucursal_id,
            'remoteSequence', v_existing.remote_sequence::text,
            'stockBefore', v_existing.stock_before::text,
            'stockAfter', v_existing.stock_after::text,
            'appliedAt', v_existing.applied_at,
            'warningCodes', pg_catalog.to_jsonb(v_existing.warning_codes)
        );
    end if;

    -- Una fila legacy no demuestra por sí sola que exista un recibo fuerte. La
    -- RPC v1 y los grants históricos podían crear movimientos sin ledger v2, y
    -- reutilizar esa identidad aplicaría el stock por segunda vez. La comprobación
    -- permanece tenant-scoped: la misma UUID legacy de otro negocio no bloquea
    -- una identidad v2 válida en este negocio.
    if exists (
        select 1
          from public.movimientos_stock as legacy
         where legacy.id = p_operation_id
           and legacy.negocio_id = p_negocio_id
    ) then
        return pg_catalog.jsonb_build_object(
            'contractVersion', '2.0',
            'outcome', 'UNKNOWN_LEGACY',
            'code', 'LEGACY_EVIDENCE_AMBIGUOUS',
            'negocioId', p_negocio_id,
            'operationId', p_operation_id,
            'authority', v_authority,
            'productoId', p_producto_id,
            'sucursalId', p_sucursal_id,
            'payloadHash', p_payload_hash
        );
    end if;

    if v_authority = 'BRANCH' then
        -- T029 confirmo que sucursales no expone estado activo. No se inventa
        -- esa evidencia: se fija y valida la fila real y su pertenencia tenant.
        perform 1
          from public.sucursales as s
         where s.id = p_sucursal_id
           and s.negocio_id = p_negocio_id
         for share;
        if not found then
            return pg_catalog.jsonb_build_object(
                'contractVersion', '2.0',
                'outcome', 'REJECTED',
                'code', 'BRANCH_NOT_FOUND_OR_FORBIDDEN',
                'negocioId', p_negocio_id,
                'operationId', p_operation_id,
                'authority', v_authority,
                'productoId', p_producto_id,
                'sucursalId', p_sucursal_id
            );
        end if;
    end if;

    -- Ambos modos bloquean producto primero. En BRANCH es solo la proyeccion;
    -- la autoridad que determina stock_before/stock_after sigue siendo la branch.
    select p.stock_actual
      into v_global_before
      from public.productos as p
     where p.id = p_producto_id
       and p.negocio_id = p_negocio_id
     for update;
    if not found then
        return pg_catalog.jsonb_build_object(
            'contractVersion', '2.0',
            'outcome', 'REJECTED',
            'code', 'PRODUCT_NOT_FOUND',
            'negocioId', p_negocio_id,
            'operationId', p_operation_id,
            'authority', v_authority,
            'productoId', p_producto_id,
            'sucursalId', p_sucursal_id
        );
    end if;
    if v_global_before is null then
        return pg_catalog.jsonb_build_object(
            'contractVersion', '2.0',
            'outcome', 'REJECTED',
            'code', 'SCOPE_NOT_INITIALIZED',
            'negocioId', p_negocio_id,
            'operationId', p_operation_id,
            'authority', v_authority,
            'productoId', p_producto_id,
            'sucursalId', p_sucursal_id
        );
    end if;

    if v_authority = 'GLOBAL' then
        -- Un producto con filas branch no puede aceptar silenciosamente GLOBAL.
        if exists (
            select 1
              from public.inventario_sucursales as inventory
             where inventory.producto_id = p_producto_id
        ) then
            return pg_catalog.jsonb_build_object(
                'contractVersion', '2.0',
                'outcome', 'REJECTED',
                'code', 'AUTHORITY_SCOPE_MISMATCH',
                'negocioId', p_negocio_id,
                'operationId', p_operation_id,
                'authority', v_authority,
                'productoId', p_producto_id,
                'sucursalId', null
            );
        end if;
        v_stock_before := v_global_before;
    else
        -- Se bloquean todas las filas branch en orden, no solo la solicitada: la
        -- suma es parte de la precondicion y debe permanecer estable hasta COMMIT.
        perform 1
          from public.inventario_sucursales as inventory
         where inventory.producto_id = p_producto_id
         order by inventory.sucursal_id
         for update;

        select inventory.stock_actual
          into v_branch_before
          from public.inventario_sucursales as inventory
         where inventory.sucursal_id = p_sucursal_id
           and inventory.producto_id = p_producto_id;
        if not found then
            return pg_catalog.jsonb_build_object(
                'contractVersion', '2.0',
                'outcome', 'REJECTED',
                'code', 'SCOPE_NOT_INITIALIZED',
                'negocioId', p_negocio_id,
                'operationId', p_operation_id,
                'authority', v_authority,
                'productoId', p_producto_id,
                'sucursalId', p_sucursal_id
            );
        end if;

        select pg_catalog.count(*)::bigint,
               coalesce(pg_catalog.sum(inventory.stock_actual::bigint), 0::bigint)
          into v_branch_count, v_branch_total
          from public.inventario_sucursales as inventory
         where inventory.producto_id = p_producto_id;

        if v_branch_count = 0 or v_branch_total is distinct from v_global_before::bigint then
            return pg_catalog.jsonb_build_object(
                'contractVersion', '2.0',
                'outcome', 'REJECTED',
                'code', 'AUTHORITY_PROJECTION_DIVERGED',
                'negocioId', p_negocio_id,
                'operationId', p_operation_id,
                'authority', v_authority,
                'productoId', p_producto_id,
                'sucursalId', p_sucursal_id
            );
        end if;
        v_stock_before := v_branch_before;
    end if;

    if p_effect_kind = 'DELTA' then
        if v_stock_before::bigint + v_effect_value_bigint < -2147483648
           or v_stock_before::bigint + v_effect_value_bigint > 2147483647
        then
            return pg_catalog.jsonb_build_object(
                'contractVersion', '2.0',
                'outcome', 'REJECTED',
                'code', 'INVALID_EFFECT',
                'negocioId', p_negocio_id,
                'operationId', p_operation_id,
                'authority', v_authority,
                'productoId', p_producto_id,
                'sucursalId', p_sucursal_id
            );
        end if;
        v_stock_after := (v_stock_before::bigint + v_effect_value_bigint)::integer;
    else
        v_stock_after := v_effect_value_integer;
    end if;

    if v_authority = 'BRANCH' then
        v_branch_after_bigint := v_stock_after::bigint;
        v_global_after_bigint := v_global_before::bigint
            + (v_branch_after_bigint - v_branch_before::bigint);
        if v_global_after_bigint < -2147483648 or v_global_after_bigint > 2147483647 then
            return pg_catalog.jsonb_build_object(
                'contractVersion', '2.0',
                'outcome', 'REJECTED',
                'code', 'INVALID_EFFECT',
                'negocioId', p_negocio_id,
                'operationId', p_operation_id,
                'authority', v_authority,
                'productoId', p_producto_id,
                'sucursalId', p_sucursal_id
            );
        end if;
    end if;

    -- El scope advisory lock protege tambien el caso sin fila de contador. La
    -- fila se crea solamente en la ruta APPLIED; un conflicto deja cero huella.
    perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'inventory-v2-scope:' || p_negocio_id::text || ':'
            || v_authority || ':' || coalesce(p_sucursal_id::text, 'GLOBAL'),
            0
        )
    );

    select sequence_scope.scope_id, sequence_scope.last_remote_sequence
      into v_counter_id, v_current_sequence
      from public.inventario_secuencias_v2 as sequence_scope
     where sequence_scope.negocio_id = p_negocio_id
       and sequence_scope.authority_kind = v_authority
       and sequence_scope.sucursal_id is not distinct from p_sucursal_id
     for update;
    v_counter_exists := found;
    if not v_counter_exists then
        v_current_sequence := 0;
    end if;

    if p_effect_kind = 'ABSOLUTE'
       and p_expected_remote_sequence is distinct from v_current_sequence
    then
        return pg_catalog.jsonb_build_object(
            'contractVersion', '2.0',
            'outcome', 'CONFLICT',
            'code', 'STALE_ABSOLUTE_BASE',
            'negocioId', p_negocio_id,
            'operationId', p_operation_id,
            'payloadHash', p_payload_hash,
            'authority', v_authority,
            'productoId', p_producto_id,
            'sucursalId', p_sucursal_id,
            'expectedRemoteSequence', p_expected_remote_sequence::text,
            'actualRemoteSequence', v_current_sequence::text
        );
    end if;

    if v_current_sequence = 9223372036854775807 then
        return pg_catalog.jsonb_build_object(
            'contractVersion', '2.0',
            'outcome', 'REJECTED',
            'code', 'REMOTE_UNAVAILABLE',
            'negocioId', p_negocio_id,
            'operationId', p_operation_id,
            'authority', v_authority,
            'productoId', p_producto_id,
            'sucursalId', p_sucursal_id
        );
    end if;
    v_next_sequence := v_current_sequence + 1;

    -- A partir de aqui no existe ningun RETURN de negocio. Si cualquier DML o
    -- constraint falla, PostgreSQL aborta la llamada y revierte stock, contador y
    -- ledger juntos. Por eso no puede confirmarse uno sin los otros.
    if v_authority = 'GLOBAL' then
        update public.productos as p
           set stock_actual = v_stock_after
         where p.id = p_producto_id
           and p.negocio_id = p_negocio_id;
        get diagnostics v_affected_rows = row_count;
        if v_affected_rows <> 1 then
            raise exception using
                errcode = '40001',
                message = 'INVENTORY_V2_ATOMIC_WRITE_FAILED';
        end if;
    else
        update public.inventario_sucursales as inventory
           set stock_actual = v_stock_after
         where inventory.sucursal_id = p_sucursal_id
           and inventory.producto_id = p_producto_id;
        get diagnostics v_affected_rows = row_count;
        if v_affected_rows <> 1 then
            raise exception using
                errcode = '40001',
                message = 'INVENTORY_V2_ATOMIC_WRITE_FAILED';
        end if;

        update public.productos as p
           set stock_actual = v_global_after_bigint::integer
         where p.id = p_producto_id
           and p.negocio_id = p_negocio_id;
        get diagnostics v_affected_rows = row_count;
        if v_affected_rows <> 1 then
            raise exception using
                errcode = '40001',
                message = 'INVENTORY_V2_ATOMIC_WRITE_FAILED';
        end if;
    end if;

    if v_counter_exists then
        update public.inventario_secuencias_v2 as sequence_scope
           set last_remote_sequence = v_next_sequence
         where sequence_scope.scope_id = v_counter_id;
        get diagnostics v_affected_rows = row_count;
        if v_affected_rows <> 1 then
            raise exception using
                errcode = '40001',
                message = 'INVENTORY_V2_ATOMIC_WRITE_FAILED';
        end if;
    else
        insert into public.inventario_secuencias_v2 (
            negocio_id,
            authority_kind,
            sucursal_id,
            last_remote_sequence
        ) values (
            p_negocio_id,
            v_authority,
            p_sucursal_id,
            v_next_sequence
        );
        get diagnostics v_affected_rows = row_count;
        if v_affected_rows <> 1 then
            raise exception using
                errcode = '40001',
                message = 'INVENTORY_V2_ATOMIC_WRITE_FAILED';
        end if;
    end if;

    v_applied_at := pg_catalog.clock_timestamp();
    insert into public.inventario_operaciones_v2 (
        negocio_id,
        operacion_id,
        payload_version,
        payload_hash,
        authority_kind,
        producto_id,
        sucursal_id,
        effect_kind,
        effect_value,
        tipo,
        referencia_id,
        fecha_origen,
        expected_remote_sequence,
        remote_sequence,
        stock_before,
        stock_after,
        applied_at,
        applied_by,
        warning_codes
    ) values (
        p_negocio_id,
        p_operation_id,
        p_contract_version,
        p_payload_hash,
        v_authority,
        p_producto_id,
        p_sucursal_id,
        p_effect_kind,
        v_effect_value_integer,
        p_tipo,
        p_referencia_id,
        p_fecha_origen,
        p_expected_remote_sequence,
        v_next_sequence,
        v_stock_before,
        v_stock_after,
        v_applied_at,
        v_actor_id,
        v_warning_codes
    );
    get diagnostics v_affected_rows = row_count;
    if v_affected_rows <> 1 then
        raise exception using
            errcode = '40001',
            message = 'INVENTORY_V2_ATOMIC_WRITE_FAILED';
    end if;

    return pg_catalog.jsonb_build_object(
        'contractVersion', '2.0',
        'outcome', 'APPLIED',
        'code', 'APPLIED',
        'negocioId', p_negocio_id,
        'operationId', p_operation_id,
        'payloadHash', p_payload_hash,
        'authority', v_authority,
        'productoId', p_producto_id,
        'sucursalId', p_sucursal_id,
        'remoteSequence', v_next_sequence::text,
        'stockBefore', v_stock_before::text,
        'stockAfter', v_stock_after::text,
        'appliedAt', v_applied_at,
        'warningCodes', pg_catalog.to_jsonb(v_warning_codes)
    );
end;
